import sys

def insert_dist(dist, c, dist_map, diff):
    if dist <= (13 + diff):
        dist_map[c] = abs(dist - diff)
    else:
        dist_map[c] = 26 + diff - dist

def solve(input_stream, output_stream):
    dist_a = {}
    dist_c = {}
    dist_t = {}
    dist_g = {}

    for i, c in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZ"):
        dist = i
        insert_dist(dist, c, dist_a, 0)
        insert_dist(dist, c, dist_c, 2)
        if dist <= 6:
            dist_t[c] = 7 + dist
        else:
            dist_t[c] = abs(dist - 19)
        insert_dist(dist, c, dist_g, 6)

    n_line = input_stream.readline()
    n = int(n_line.strip())

    s_line = input_stream.readline()
    s = s_line.strip()

    char_vec = list(s)
    min_sum = -1
    for i in range(n - 3):
        sum_val = (dist_a[char_vec[i]] +
                   dist_c[char_vec[i + 1]] +
                   dist_t[char_vec[i + 2]] +
                   dist_g[char_vec[i + 3]])
        if min_sum == -1 or sum_val < min_sum:
            min_sum = sum_val

    output_stream.write(str(min_sum) + "\n")

def main():
    solve(sys.stdin, sys.stdout)

if __name__ == "__main__":
    main()

